 /**
  * Sanitize an SVG string to remove potentially harmful content.
+ * Removes script tags, event handlers, and other dangerous elements.
  */

+const UNSAFE_ELEMENTS = ['script', 'use'];
+const UNSAFE_ATTRIBUTES = /^on/i;
+const UNSAFE_HREF = /^\s*javascript:/i;
+
+/**
+ * Remove unsafe elements and attributes from an SVG DOM tree.
+ * @param {SVGElement} svgElement - The SVG element to sanitize.
+ */
+const sanitizeSVGElement = function (svgElement) {
+    // Remove unsafe elements
+    for (const tag of UNSAFE_ELEMENTS) {
+        const elements = svgElement.querySelectorAll(tag);
+        for (const element of elements) {
+            element.parentNode.removeChild(element);
+        }
+    }
+
+    // Walk all elements and remove unsafe attributes
+    const allElements = svgElement.querySelectorAll('*');
+    for (const element of allElements) {
+        const attributeNames = element.getAttributeNames ? element.getAttributeNames() : [];
+        for (const attr of attributeNames) {
+            // Remove event handler attributes (onclick, onload, etc.)
+            if (UNSAFE_ATTRIBUTES.test(attr)) {
+                element.removeAttribute(attr);
+            }
+            // Remove javascript: hrefs
+            if ((attr === 'href' || attr === 'xlink:href') &&
+                UNSAFE_HREF.test(element.getAttribute(attr))) {
+                element.removeAttribute(attr);
+            }
+        }
+    }
+
+    // Also sanitize the root element's attributes
+    const rootAttrs = svgElement.getAttributeNames ? svgElement.getAttributeNames() : [];
+    for (const attr of rootAttrs) {
+        if (UNSAFE_ATTRIBUTES.test(attr)) {
+            svgElement.removeAttribute(attr);
+        }
+    }
+};
+
+module.exports = sanitizeSVGElement;
